SELECT (COUNT(DISTINCT v.cik) * 100.0 / COUNT(c.cik)) AS percentage_with_revenue
FROM companies c
LEFT JOIN v_revenue v ON c.cik = v.cik;

WITH apple_cik AS (
    SELECT cik FROM companies WHERE ticker = 'AAPL'
),
revenue_2024 AS (
    SELECT value AS revenue_2024 FROM v_revenue WHERE cik = (SELECT cik FROM apple_cik) AND fiscal_year = 2024
),
revenue_2025 AS (
    SELECT value AS revenue_2025 FROM v_revenue WHERE cik = (SELECT cik FROM apple_cik) AND fiscal_year = 2025
)
SELECT ((revenue_2025 - revenue_2024) / revenue_2024) * 100 AS growth_percentage
FROM revenue_2024, revenue_2025;

